   99  					+ " e WHERE e."
  100  					+ attribute
  101  					+ " = :"
  102  					+ parameterName;
  103  
  104  			TypedQuery<T> query = entityManager.createQuery(jpql, entityClass);
  105  			query.setParameter(parameterName, value);
