  116  	public <T> List<T> findByFields(
  117  			Class<T> entityClass,
  118  			Map<String, Object> searchFields
  119  	) {
  120  
  121  		if (entityClass == null) {
  122  			throw new IllegalArgumentException("The search class must not be null.");
  123  		}
  124  
  125  		EntityManager entityManager = jpaUtil.getEntityManager();
  126  
  127  		try {
  128  			StringBuilder jpql = new StringBuilder();
  129  
  130  			jpql.append("SELECT e FROM ")
  131  					.append(entityClass.getSimpleName())
  132  					.append(" e");
  133  
  134  			if (searchFields != null && !searchFields.isEmpty()) {
  135  				jpql.append(" WHERE ");
  136  
  137  				int index = 0;
  138  
  139  				for (String field : searchFields.keySet()) {
  140  					if (field == null || field.trim().isEmpty()) {
  141  						throw new IllegalArgumentException("A search field must not be empty.");
  142  					}
  143  
  144  					if (index > 0) {
  145  						jpql.append(" AND ");
  146  					}
  147  
  148  					String parameterName = generateParameterName(field);
  149  
  150  					jpql.append("e.")
  151  							.append(field)
  152  							.append(" = :")
  153  							.append(parameterName);
  154  
  155  					index++;
  156  				}
  157  			}
  158  
  159  			TypedQuery<T> query = entityManager.createQuery(jpql.toString(), entityClass);
  160  
  161  			if (searchFields != null && !searchFields.isEmpty()) {
  162  				for (Map.Entry<String, Object> entry : searchFields.entrySet()) {
  163  					String parameterName = generateParameterName(entry.getKey());
  164  					query.setParameter(parameterName, entry.getValue());
  165  				}
  166  			}
  167  
  168  			return query.getResultList();
  169  		} finally {
  170  			entityManager.close();
  171  		}
